@extends('layouts.app') @section('title','Payment claims') @section('content') @include('titanpay::partials.header')<main class="p-6"><div class="max-w-7xl mx-auto space-y-3">@foreach($claims as $claim)<div class="bg-white border rounded-xl p-5"><div class="flex justify-between"><div><strong>{{ $claim->session?->invoice?->invoice_number }}</strong><p>{{ $claim->payer_name }} · {{ $claim->method }} · {{ formatMoneyMinor($claim->amount_minor, $claim->currency_code) }} · {{ $claim->status }}</p><p>Reference {{ $claim->reference }}</p></div>@if($claim->status==='submitted')<div class="flex gap-2"><form method="POST" action="{{ route('titanpay.claims.approve',$claim) }}">@csrf<button class="px-3 py-2 bg-green-600 text-white rounded">Approve</button></form><form method="POST" action="{{ route('titanpay.claims.reject',$claim) }}">@csrf<input name="reason" required class="border rounded p-2" placeholder="Reason"><button class="px-3 py-2 border border-red-300 text-red-700 rounded">Reject</button></form></div>@endif</div>@foreach($claim->evidence as $e)<a class="text-purple-700" href="{{ route('titanpay.claims.evidence',[$claim,$e]) }}">{{ $e->original_name }}</a>@endforeach</div>@endforeach</div></main>@endsection